function node(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function button(label,fn,cls=''){const b=node('button',cls,label);b.type='button';b.addEventListener('click',fn);return b}
function section(parent,title,link,rows){const box=node('section','section');const head=node('div','section-head');head.append(node('h2','',title));if(link)head.append(button(link,()=>showView(title==='Needs you'?'work':'find'),'quiet-link'));box.append(head);const list=node('div','list');rows.forEach(item=>list.append(row(item)));box.append(list);parent.append(box)}
function row(item){const b=button('',()=>openDetail(item),'list-row');b.append(node('span','row-mark '+(item.tone||''),item.mark));const copy=node('span','row-copy');copy.append(node('span','row-title',item.title),node('span','row-sub',item.sub));b.append(copy,node('span','row-trailing',item.trailing),node('span','chevron','›'));return b}
function heading(parent,title,sub){const h=node('div','page-title');const inner=node('div');inner.append(node('h1','',title),node('p','',sub));h.append(inner);parent.append(h)}
