function decisionPreview(){const card=node('section','decision-card');const current=decisions[state.decisionIndex];const pending=decisions.filter((_,i)=>!state.decisionAnswers[i]).length;card.append(node('div','decision-label',`Example decisions · ${pending} unanswered · design preview`));if(state.decisionList){card.append(node('h2','decision-question','All decisions'));decisions.forEach((d,i)=>{const choice=button('',()=>{state.decisionIndex=i;state.decisionList=false;render()},'decision-list-row');choice.append(node('strong','',`${i+1}. ${d.question}`),node('small','',`${d.owner} · ${state.decisionAnswers[i]||'waiting'}`));card.append(choice)});card.append(button('Back to stack',()=>{state.decisionList=false;render()},'quiet-link'));return card}card.append(node('h2','decision-question',current.question));const options=node('div','decision-options');current.options.forEach(([label,consequence,recommended])=>{const choice=button('',()=>{state.decisionAnswers[state.decisionIndex]=label;render()},'decision-option'+(recommended?' recommended':''));const title=node('strong','',label);if(recommended)title.append(node('em','','· recommended'));choice.append(title,node('small','',consequence));options.append(choice)});if(state.decisionAnswers[state.decisionIndex])card.append(node('p','decision-receipt',`Selected: ${state.decisionAnswers[state.decisionIndex]} · prototype receipt only`));else card.append(options);const nav=node('div','decision-nav');nav.append(button('← Previous',()=>{state.decisionIndex=(state.decisionIndex+decisions.length-1)%decisions.length;render()},'quiet-link'),node('span','',`${state.decisionIndex+1} of ${decisions.length}`),button('Next →',()=>{state.decisionIndex=(state.decisionIndex+1)%decisions.length;render()},'quiet-link'));card.append(nav);const links=node('div','decision-footer');links.append(button('See context',()=>watchDetail(coordinators.find(c=>c.name===current.owner)||coordinators[0]),'quiet-link'),button('Full list',()=>{state.decisionList=true;render()},'quiet-link'));card.append(links);return card}
function home(parent){heading(parent,'Coordinators','See what is happening without opening another terminal.');parent.append(node('p','watch-note','Snapshot from the local Office at 7:44 AM · Prototype data; this page does not poll live.'),decisionPreview());const grid=node('div','two-col');const left=node('div');coordinators.forEach(c=>left.append(coordinatorCard(c)));grid.append(left);const right=node('div');const head=node('div','section-head');head.append(node('h2','','Latest meaningful changes'));right.append(head);const activity=node('div','activity-list');[['7:35 AM','TBS committed a rendered-page age check'],['7:33 AM','TBS recorded the one-source rule'],['6:15 AM','Matra completed its last run']].forEach(([time,line])=>{const r=node('div','activity-row');r.append(node('strong','',line),node('span','',time));activity.append(r)});right.append(activity);const note=node('div','hero-note');note.style.marginTop='25px';note.append(node('h3','','What needs you?'),node('p','','TBS has one unread high-priority instruction. Matra is blocked by the build environment. Other detail is available inside each coordinator.'));right.append(note);grid.append(right);parent.append(grid)}
function watchDetail(c,initial='activity'){$('#detail-heading').textContent=c.name+' coordinator';const content=$('#detail-content');content.replaceChildren();content.append(node('h2','',c.name+' is '+c.state.toLowerCase()),node('p','detail-intro',c.objective),node('div','inbox-line',c.inbox));const tabs=node('div','watch-tabs');const panel=node('div');content.append(tabs,panel);function draw(view){tabs.replaceChildren();[['activity','Activity'],['inbox','Inbox'],['steer','Steer'],['raw','Full transcript']].forEach(([key,label])=>tabs.append(button(label,()=>draw(key),key===view?'selected':'')));panel.replaceChildren();if(view==='activity'){c.activity.forEach(([time,line])=>{const r=node('div','watch-fact');r.append(node('b','',line),node('span','',time));panel.append(r)});panel.append(node('p','detail-intro',c.details));}if(view==='inbox'){panel.append(node('p','detail-intro',c.details),node('div','watch-fact','Latest message: '+c.inbox));}if(view==='steer'){const form=node('form','steer-form');const input=node('textarea');input.placeholder='Send a correction or next priority…';input.required=true;form.append(input);const send=node('button','primary','Send instruction');send.type='submit';form.append(send);form.addEventListener('submit',e=>{e.preventDefault();if(!input.value.trim())return;c.inbox='Instruction queued · waiting to be read';$('#detail').close();toast('Instruction queued in this prototype');render()});panel.append(form,node('p','detail-intro','A real version would keep the draft and show accepted, read, and acted-on separately.'));}if(view==='raw'){panel.append(node('p','detail-intro','Complete chronological output, tool events, holds, commits, and run receipts would live here. The watch view stays concise.'));c.activity.forEach(([time,line])=>panel.append(node('div','watch-fact',time+' · '+line)));}}draw(initial);$('#detail').showModal()}
