function feedPost(post){const card=node('article','feed-entry post');const head=node('div','feed-entry-head');head.append(node('span','feed-kind',post.topic),node('span','feed-owner',post.by));card.append(head,node('h2','',post.title),node('p','',post.body));const actions=node('div','post-actions');if(post.source){const link=node('a','quiet-link',post.sourceLabel+' ↗');link.href=post.source;link.target='_blank';link.rel='noopener noreferrer';actions.append(link)}if(post.item)actions.append(button(post.item.kind==='pull'?'Open PR →':post.item.kind==='issue'?'Open issue →':post.topic==='Listen'?'Open episode →':'Open detail →',()=>openDetail(post.item),'quiet-link'));actions.append(button(state.saved.has(post.id)?'Saved ✓':'Save',()=>{state.saved.has(post.id)?state.saved.delete(post.id):state.saved.add(post.id);render()},'quiet-link'));actions.append(button(state.reactions[post.id]?'Loved ♥':'Love ♡',()=>{state.reactions[post.id]=!state.reactions[post.id];render()},'quiet-link'));card.append(actions);return card}
function work(parent){heading(parent,'Feed','A little window into the outside world—and your work.');parent.append(node('p','watch-note','Design preview · short posts adapted from archived September 22 emails. Links open their original sources.'));const filters=node('div','chips');['For you','Discoveries','AI & research','History & ideas','Work','Listen','Saved'].forEach(label=>filters.append(button(label,()=>{state.feedFilter=label;render()},'chip'+(state.feedFilter===label?' selected':''))));parent.append(filters);const stream=node('div','feed-stream');feedPosts.filter(post=>state.feedFilter==='For you'||state.feedFilter==='Saved'&&state.saved.has(post.id)||post.topic===state.feedFilter).forEach(post=>stream.append(feedPost(post)));if(!stream.children.length)stream.append(node('p','empty','Nothing here yet. Save a post to collect it.'));parent.append(stream)}
function find(parent){heading(parent,'Find','A single doorway into everything in Office.');const input=node('input','search-input');input.type='search';input.placeholder='Search projects, files, conversations, GitHub…';input.value=state.search;input.setAttribute('aria-label','Search Office');parent.append(input);const chips=node('div','chips');['All','Work','Files','GitHub','System'].forEach(v=>{const b=button(v,()=>{state.filter=v;render()},'chip'+(state.filter===v?' selected':''));chips.append(b)});parent.append(chips);const results=node('div','list');parent.append(results);function draw(){state.search=input.value;results.replaceChildren();const q=state.search.toLowerCase();let found=items.filter(x=>(x.title+' '+x.sub+' '+x.description).toLowerCase().includes(q));if(state.filter==='Files')found=found.filter(x=>x.id==='file');if(state.filter==='GitHub')found=found.filter(x=>['issue','pr'].includes(x.id));if(state.filter==='System')found=found.filter(x=>x.id==='system');if(state.filter==='Work')found=found.filter(x=>!['file','system'].includes(x.id));found.forEach(x=>results.append(row(x)));if(!found.length)results.append(node('p','empty','No matching items in this prototype.'))}input.addEventListener('input',draw);draw();input.focus()}
function showView(view){state.view=view;location.hash=view;render()}
function render(){const parent=$('#main');parent.replaceChildren();$('#breadcrumb').textContent=state.view==='home'?'Watch':state.view==='work'?'Feed':'Find';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===state.view));({home,work,find}[state.view]||home)(parent)}
function openDetail(item){$('#detail-heading').textContent=item.title;const content=$('#detail-content');content.replaceChildren(node('h2','',item.title),node('p','detail-intro',item.description));if(item.repo&&item.number){const ref=node('p','object-ref',`${item.repo} #${item.number} · ${item.kind==='pull'?'Pull request':'Issue'}`);content.append(ref);const url=`https://github.com/${item.repo}/${item.kind==='pull'?'pull':'issues'}/${item.number}`;const link=node('a','source-link','Open on GitHub ↗');link.href=url;link.target='_blank';link.rel='noopener noreferrer';content.append(link)}else if(item.id==='email'){content.append(node('p','reader-preview','Email reader preview: the full message would be shown here with the original subject, sender, date, and linked references. This sample contains no real email content.'))}else if(item.id==='podcast'){const player=node('div','player-preview');player.append(node('strong','','Episode player'));player.append(node('p','','Playback will be connected to the existing Office audio endpoint. Chapters, transcript and source links remain below.'));content.append(player)}else content.append(button(item.primary,()=>action(item),'primary detail-primary'));const facts=node('div','detail-facts');item.facts.forEach(([a,b])=>{const line=node('div');line.append(node('span','',a),node('b','',b));facts.append(line)});content.append(facts);item.sections.forEach(([name,text])=>{const d=node('details');d.append(node('summary','',name),node('p','',text));content.append(d)});$('#detail').showModal()}
function project(p){const item={title:p.name,description:p.sub,primary:'Open active work',facts:[['Project',p.name],['Status',p.sub]],sections:[['Tasks and agents','Current conversations and all retained history.'],['Files','Local checkout and GitHub source, with revisioned readers and editing.'],['GitHub','Issues, pull requests, checks, diffs and reviews.'],['Outputs','Artifacts, previews and published results.'],['Activity','The complete project timeline.']]};openDetail(item)}
function action(item){if(item.id==='permission'){item.title='Permission answered';item.description='Allowed once. The agent can continue.';$('#detail').close();toast('Permission recorded in this prototype');render();return}$('#detail').close();toast(`${item.primary} is represented as a focused destination in this prototype`)}
function toast(text){const t=$('#toast');t.textContent=text;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,3500)}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));$('#new-task').addEventListener('click',()=>$('#composer').showModal());$('#back').addEventListener('click',()=>$('#detail').close());$('#close-composer').addEventListener('click',()=>$('#composer').close());$('#places').addEventListener('click',()=>openDetail(items.find(x=>x.id==='system')));$('#status').addEventListener('click',()=>openDetail(items.find(x=>x.id==='system')));$('#profile').addEventListener('click',()=>toast('Profile and preferences would open here'));$('#detail-menu').addEventListener('click',()=>toast('Secondary actions would appear here'));$('#task-form').addEventListener('submit',e=>{e.preventDefault();const prompt=$('#task-prompt').value.trim();if(!prompt)return;state.tasks.push(prompt);$('#composer').close();$('#task-form').reset();toast('Task added to this prototype');showView('work')});window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['home','work','find'].includes(v)&&v!==state.view){state.view=v;render()}});state.view=['home','work','find'].includes(location.hash.slice(1))?location.hash.slice(1):'home';render();
